<script lang="ts">
  import { components } from "$lib/dynamic_layout_test/all_components.svelte";
  import GenericJsonSchemaFormDialog from "$lib/dialogs/GenericJsonSchemaFormDialog.svelte";
  import TabbedJsonSchemaFormDialog from "$lib/dialogs/TabbedJsonSchemaFormDialog.svelte";
  import {
    additionalContext, initializeContexts
  } from "$lib/state/app-state.svelte";
  import { Inspect } from "svelte-inspect-value";
  import ChangeParentDialog from "$lib/dialogs/ChangeParentDialog.svelte";

  import GlobalSettingDialog from "$lib/dialogs/GlobalSettingDialog.svelte";
  import DataSourceDialog from "$lib/dialogs/DataSourceDialog.svelte";
  import { NodeRepository, queryState } from "$lib/database/nodeRepository.svelte";
  import CssClassDialog from "$lib/dialogs/CssClassDialog.svelte";
  import { SCHEMA_NODE_TYPES } from "$lib/dynamic_layout_test/schema_types.svelte";

  import { NodePersistence } from "$lib/database/nodePersistence.svelte";
  import { getNodesQuery } from "$lib/database/evolu/queries";
  import { evolu } from "$lib/database/evolu/evolu_instance";
  import {
    type DynamicLayoutNode, getLabel
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { LiveNodeDataState } from "$lib/contexts/liveNodeData.context.svelte";
  import AddNodeDialog from "$lib/dialogs/AddNodeDialog.svelte";
  import DynamicLayoutByNode from "$lib/components/DynamicLayoutByNode.svelte";
  import { ExampleLayout } from "$lib/dynamic_layout_test/gettingStartedLayout/00_root";
  import { SettingsRepository } from "$lib/database/settingsRepository.svelte";
  import { Button } from "$lib/components/ui/button";
  import SveltePortalSource from "$lib/blocks/svelte-utils/portal/SveltePortalSource.svelte";
  import { Switch } from "$lib/components/ui/switch";
	import { page } from '$app/state';
  import type { NodeId } from "$lib/database/evolu/datastructure";
  import { convertDbNodeToDynamicLayoutNode } from "$lib/database/layoutDbNodeConverter";

  let node = $state<DynamicLayoutNode | null>(null);

  $effect(() => {
     NodeRepository.getNodeAsync(page.params.slug as NodeId).then(_node => node = convertDbNodeToDynamicLayoutNode( _node));
  });


  const query = getNodesQuery({});

  const nodes = $derived(additionalContext.DEBUG_MODE ? queryState(() => query, evolu, {
    useLoadQueryResult: true
  }) : null);

  const nodeDatas = $derived(additionalContext.DEBUG_MODE ? queryState(() => evolu.createQuery(db => db.selectFrom("nodeData").selectAll()), evolu, {
    useLoadQueryResult: true
  }) : null);


  let shouldShowExampleLayout = $state(false);

  SettingsRepository.getSettingByKey("hasShownExampleLayout").then(setting => {
    shouldShowExampleLayout = !setting?.value;
  });

  SCHEMA_NODE_TYPES.TYPES_LIST = Object.keys(components);
</script>


<svelte:head>
  <title>Dashboard</title>
</svelte:head>

{#if node}
  <SveltePortalSource name="header-title">
    {getLabel(node)}
  </SveltePortalSource>
{/if}

<SveltePortalSource name="sidebar-header">
  <span class="flex items-center">
    <span class="truncate" style="flex: 1">Edit Mode:</span>
      &nbsp;
    <Switch bind:checked={additionalContext.editMode}>
    </Switch>
  </span>
</SveltePortalSource>

{#if additionalContext.DEBUG_MODE}
  <Inspect value={$state.snapshot(nodes?.rows)} name="Nodes" expandLevel={0} />
  <Inspect value={$state.snapshot(nodeDatas?.rows)} name="NodeDatas" expandLevel={0} />
  <Inspect value={$state.snapshot(LiveNodeDataState)} name="LiveNodeData" />
{/if}


{#if shouldShowExampleLayout}
  <h2 class="text-lg">Hi, this shows an example Layout. Click here if you want to hide the example layout and begin with
    your dashboard.</h2>
  <br />

  <Button onclick={() => {
    shouldShowExampleLayout = false;
    SettingsRepository.addSetting({
      key: "hasShownExampleLayout",
      value: true
    });
  }}>Hide Example Layout & let me create my own dashboard now
  </Button>

  <br />
  <br />
  <DynamicLayoutByNode node={ExampleLayout} />
{:else}
  {#if node}
    <DynamicLayoutByNode node={node} />
  {/if}
{/if}
